{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `MapleMonk.zouk_bbf_store_level` AS WITH config AS ( SELECT 0.60 AS Sales_Weight, 0.10 AS AOV_Weight, 0.10 AS Bulk_Weight, 0.10 AS Repeat_Weight, 0.10 AS NonDiscount_Weight, 1 AS Bulk_Orders_Required, 1.00 AS NonDiscount_Threshold_Pct, 20000.0 AS Bulk_Order_Cutoff ), store_master AS ( SELECT SAFE_CAST(Location_ID AS INT64) AS location_id, Store_Code, Store_Name FROM `MapleMonk.Zouk_EBO_Store_Master` QUALIFY ROW_NUMBER() OVER (PARTITION BY SAFE_CAST(Location_ID AS INT64) ORDER BY Store_Code) = 1 ), base AS ( SELECT DATE(s.order_timestamp) AS Date, DATE_TRUNC(DATE(s.order_timestamp), WEEK(MONDAY)) AS Week_Start, DATE_TRUNC(DATE(s.order_timestamp), MONTH) AS Month, sm.Store_Code, sm.Store_Name, s.ORDER_ID, s.TOTAL_SALES, s.DISCOUNT, s.shopify_new_customer_flag FROM `MapleMonk.zouk_SHOPIFY_FACT_ITEMS` s LEFT JOIN store_master sm ON s.location_id = sm.location_id WHERE s.FINAL_MARKETPLACE = \'EBO\' AND LOWER(IFNULL(s.order_status, \'\')) NOT LIKE \'%cancel%\' ), order_level AS ( SELECT Week_Start, Store_Code, ORDER_ID, SUM(TOTAL_SALES) AS Order_Value, MAX(shopify_new_customer_flag) AS new_customer_flag FROM base WHERE Store_Code IS NOT NULL GROUP BY Week_Start, Store_Code, ORDER_ID ), weekly_store_agg AS ( SELECT Week_Start, Store_Code, Store_Name, SUM(TOTAL_SALES) AS Total_Sales, COUNT(DISTINCT ORDER_ID) AS Total_Orders, SUM(CASE WHEN IFNULL(DISCOUNT, 0) = 0 THEN TOTAL_SALES ELSE 0 END) AS Non_Discounted_Sales FROM base WHERE Store_Code IS NOT NULL GROUP BY Week_Start, Store_Code, Store_Name ), bulk_orders_agg AS ( SELECT ol.Week_Start, ol.Store_Code, COUNT(DISTINCT ol.ORDER_ID) AS Bulk_Orders FROM order_level ol, config c WHERE ol.Order_Value >= c.Bulk_Order_Cutoff GROUP BY ol.Week_Start, ol.Store_Code ), repeat_orders_agg AS ( SELECT Week_Start, Store_Code, COUNT(DISTINCT ORDER_ID) AS Repeat_Orders FROM order_level WHERE new_customer_flag = \'Repeat\' GROUP BY Week_Start, Store_Code ), weekly_targets AS ( SELECT DATE_TRUNC(Date, WEEK(MONDAY)) AS Week_Start, Store_Code, SUM(Target) AS Week_Target FROM `MapleMonk.zouk_store_target_vs_achievement` WHERE Store_Code IS NOT NULL GROUP BY Week_Start, Store_Code ), monthly_country_agg AS ( SELECT Month, SAFE_DIVIDE(SUM(TOTAL_SALES), COUNT(DISTINCT ORDER_ID)) AS Country_Monthly_AOV FROM base WHERE Store_Code IS NOT NULL GROUP BY Month ), date_spine AS ( SELECT DISTINCT Week_Start FROM weekly_store_agg UNION DISTINCT SELECT DISTINCT Week_Start FROM weekly_targets ), full_grid AS ( SELECT d.Week_Start, sm.Store_Code, sm.Store_Name FROM date_spine d CROSS JOIN store_master sm ), joined AS ( SELECT fg.Week_Start, fg.Store_Code, fg.Store_Name, IFNULL(wsa.Total_Sales, 0) AS Total_Sales, IFNULL(wsa.Total_Orders, 0) AS Total_Orders, IFNULL(wsa.Non_Discounted_Sales, 0) AS Non_Discounted_Sales, IFNULL(boa.Bulk_Orders, 0) AS Bulk_Orders, IFNULL(roa.Repeat_Orders, 0) AS Repeat_Orders, IFNULL(wt.Week_Target, 0) AS Sales_Target FROM full_grid fg LEFT JOIN weekly_store_agg wsa ON fg.Week_Start = wsa.Week_Start AND fg.Store_Code = wsa.Store_Code LEFT JOIN bulk_orders_agg boa ON fg.Week_Start = boa.Week_Start AND fg.Store_Code = boa.Store_Code LEFT JOIN repeat_orders_agg roa ON fg.Week_Start = roa.Week_Start AND fg.Store_Code = roa.Store_Code LEFT JOIN weekly_targets wt ON fg.Week_Start = wt.Week_Start AND fg.Store_Code = wt.Store_Code ), metrics AS ( SELECT j.*, SAFE_DIVIDE(j.Total_Sales, j.Total_Orders) AS AOV, mca.Country_Monthly_AOV AS AOV_Target, SAFE_DIVIDE(j.Non_Discounted_Sales, j.Total_Sales) AS Non_Discounted_Pct, MAX(j.Repeat_Orders) OVER (PARTITION BY j.Week_Start) AS Repeat_Target FROM joined j LEFT JOIN monthly_country_agg mca ON DATE_TRUNC(j.Week_Start, MONTH) = mca.Month ) SELECT m.Week_Start, m.Store_Code, m.Store_Name, m.Total_Sales, m.Sales_Target, ROUND(LEAST(SAFE_DIVIDE(m.Total_Sales, m.Sales_Target), 1.0) * c.Sales_Weight * 100, 2) AS Sales_Target_Points, ROUND(m.AOV, 2) AS AOV, ROUND(m.AOV_Target, 2) AS AOV_Target, ROUND(LEAST(SAFE_DIVIDE(m.AOV, m.AOV_Target), 1.0) * c.AOV_Weight * 100, 2) AS AOV_Target_Points, m.Bulk_Orders, CAST(c.Bulk_Orders_Required AS FLOAT64) AS Bulk_Orders_Target, IF(m.Bulk_Orders >= c.Bulk_Orders_Required, c.Bulk_Weight * 100, 0.0) AS Bulk_Orders_Target_Points, m.Repeat_Orders AS Repeat_Customers, m.Repeat_Target AS Repeat_Customers_Target, ROUND(LEAST(SAFE_DIVIDE(m.Repeat_Orders, m.Repeat_Target), 1.0) * c.Repeat_Weight * 100, 2) AS Repeat_Customers_Target_Points, ROUND(m.Non_Discounted_Pct * 100, 2) AS Non_Discounted_Sales_Pct, ROUND(c.NonDiscount_Threshold_Pct * 100, 2) AS Non_Discounted_Sales_Target, ROUND(LEAST(SAFE_DIVIDE(m.Non_Discounted_Pct, c.NonDiscount_Threshold_Pct), 1.0) * c.NonDiscount_Weight * 100, 2) AS Non_Discounted_Sales_Target_Points, ROUND( LEAST(SAFE_DIVIDE(m.Total_Sales, m.Sales_Target), 1.0) * c.Sales_Weight * 100 + LEAST(SAFE_DIVIDE(m.AOV, m.AOV_Target), 1.0) * c.AOV_Weight * 100 + IF(m.Bulk_Orders >= c.Bulk_Orders_Required, c.Bulk_Weight * 100, 0.0) + LEAST(SAFE_DIVIDE(m.Repeat_Orders, m.Repeat_Target), 1.0) * c.Repeat_Weight * 100 + LEAST(SAFE_DIVIDE(m.Non_Discounted_Pct, c.NonDiscount_Threshold_Pct), 1.0) * c.NonDiscount_Weight * 100 , 2) AS Overall_Target_Points FROM metrics m CROSS JOIN config c ; select * from maplemonk.zouk_bbf_store_level",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            